def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_after = bins - item
    target_fill_ratio = 0.8
    target_remaining = (1 - target_fill_ratio) * bins
    return np.where(remaining_after >= 0, -np.abs(remaining_after - target_remaining), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_after = bins - item
    return np.where(remaining_after >= 0, -np.abs(remaining_after - item), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_after = bins - item
    extra_items = remaining_after // item
    return np.where(remaining_after >= 0, extra_items, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_after = bins - item
    extra_items = remaining_after // item
    return np.where(remaining_after >= 0, extra_items * np.sqrt(remaining_after), -np.inf)
